class Solution {

	/*
		Time Complexity : O(n/2*n/2) + O(n*n/2)
		Space Complexity : O(1)
	*/

public:
    void rotate(vector<vector<int>>& matrix) {
        int n = matrix.size();

        // Take a tranpose of the matrix
        for(int i=0; i<n; i++){
            for(int j=i+1; j<n; j++){
                swap(matrix[i][j], matrix[j][i]);
            }
        }

        // Reverse each row of the matrix to get the output
        for(int i=0; i<n; i++){
            reverse(matrix[i].begin(), end(matrix[i]));
        }
    }
};,68,https://leetcode.com/problems/rotate-image,https://leetcode.com/problems/rotate-image/solutions/3361412/c-beat-100-t-c-o-n-n-2-s-c-o-1/

class Solution {
public:
    void solve(int i,int& n,vector<string> &tmp, vector<vector<string>> &ans,vector<bool> &c,vector<bool> &md,vector<bool> &td){
        if(i==n){
            ans.push_back(tmp);
            return;
        }
        string str(n,'.');
        for(int j = 0; j < n; j++){
            if((c[j]==false&&md[i-j+n]==false&&td[i+j]==false)){
                str[j] = 'Q';
                c[j] = true;md[i-j+n]=true;td[i+j] = true;
                tmp.push_back(str);
                solve(i+1,n,tmp,ans,c,md,td);
                tmp.pop_back();
                str[j] = '.';
                c[j] = false;md[i-j+n]=false;td[i+j] = false;
            }
        }
    }
    vector<vector<string>> solveNQueens(int n) {
        vector<vector<string>> ans;
        vector<string> tmp;
        vector<bool> c(n,false),md(2*n+3,false),td(2*n+3,false);
        solve(0,n,tmp,ans,c,md,td);
        return ans;
    }
};,50,https://leetcode.com/problems/n-queens,https://leetcode.com/problems/n-queens/solutions/3587894/striver-type-c-most-optimized/

class Solution {
public:
    int maxSubArray(vector<int>& nums) {    
        vector<vector<int>> dp(2, vector<int>(size(nums), -1));
        return solve(nums, 0, false, dp);
    }
    int solve(vector<int>& A, int i, bool mustPick, vector<vector<int>>& dp) {
        if(i >= size(A)) return mustPick ? 0 : -1e5;
        if(dp[mustPick][i] != -1) return dp[mustPick][i];
        if(mustPick)
            return dp[mustPick][i] = max(0, A[i] + solve(A, i+1, true, dp));
        return dp[mustPick][i] = max(solve(A, i+1, false, dp), A[i] + solve(A, i+1, true, dp));
    }
};,63,https://leetcode.com/problems/maximum-subarray,https://leetcode.com/problems/maximum-subarray/solutions/1595195/c-python-7-simple-solutions-w-explanation-brute-force-dp-kadane-divide-conquer/

class Solution {
    public int maxSubArray(int[] nums) {
        int n = nums.length;
        int max = Integer.MIN_VALUE, sum = 0;

        for(int i=0;i<n;i++){
            sum += nums[i];
            max = Math.max(sum,max);

            if(sum<0) sum = 0;
        }

        return max;
    }
