class Solution {
    public String getPermutation(int n, int k) {
        int fact[]=new int[n+1];
        fact[0]=1;
        for(int i=1; i<n;i++) fact[i]=fact[i-1]*i;
        String nums="123456789".substring(0,n);
        char[] perm=new char[n];

        for(int i=n, j=0; i>0;i--, j++) {
            int p=(k-1)/fact[i-1];
            perm[j]=nums.charAt(p);
            nums=nums.substring(0, p)+nums.substring(p+1);
            k=k-p*fact[i-1];
        }
        return new String(perm);
    }
},83,https://leetcode.com/problems/permutation-sequence,https://leetcode.com/problems/permutation-sequence/solutions/4101413/easily-understandable-beginner-friendly/

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        if(!head || !head->next||k==0)
        {
            return head;
        }
        ListNode* temp=head;
        int len=1;
        while(temp->next)
        {
            len++;
            temp=temp->next;
        }
        temp->next=head;
        k=k%len;
        k=len-k;
        while(k>0)
        {
            temp=temp->next;
            k--;
        }
        head=temp->next;
        temp->next=NULL;
        return head;
    }
};,31,https://leetcode.com/problems/rotate-list,https://leetcode.com/problems/rotate-list/solutions/3943977/easy-c-solution-beats-100-users-0ms-runtime/

class Solution {
public:
    int uniquePaths(int m, int n) {
        vector<vector<int>> test(m,vector<int>(n,0));
        for(int i=0;i<n;i++){
            test[0][i]=1;
        }
        for(int i=0;i<m;i++){
            test[i][0]=1;
        }
        for(int i=1;i<m;i++){
            for(int j=1;j<n;j++){
                test[i][j]=test[i][j-1]+test[i-1][j];
            }
        }
        return test[m-1][n-1];
    }
};,46,https://leetcode.com/problems/unique-paths,https://leetcode.com/problems/unique-paths/solutions/4417906/simple-c-just-form-matrix-fill-1st-row-1st-col/

class Solution {
public:
    bool isNumber(string s) {
        return is_valid_number(s);
    }

bool is_valid_number(const std::string& s) {
    if (s.empty()) return false;

    size_t i = 0;
    if (s[i] == '+' || s[i] == '-') i++;

    bool has_integer_part = false;
    while (i < s.size() && isdigit(s[i])) {
        has_integer_part = true;
        i++;
    }

    bool has_decimal_part = false;
    if (i < s.size() && s[i] == '.') {
        i++;
        while (i < s.size() && isdigit(s[i])) {
            has_decimal_part = true;
            i++;
        }
    }

    if (i < s.size() && (s[i] == 'e' || s[i] == 'E')) {
        i++;

        if (i < s.size() && (s[i] == '+' || s[i] == '-')) i++;

        if (i == s.size() || !isdigit(s[i])) {
            return false;
        }
        while (i < s.size() && isdigit(s[i])) {
            i++;
        }
    }
    return i == s.size() && (has_integer_part || has_decimal_part);
}
};,71,https://leetcode.com/problems/valid-number,https://leetcode.com/problems/valid-number/solutions/4050542/valid-number-c-solution/

public class Solution {
    public int[] PlusOne(int[] digits) {
        List<int> ans=new();
        // start from least significant
        int i=digits.Length-1;
        bool easy=false;
        while(i>-1){
            if(digits[i]<9){
                int x=i+1;
                while(x<digits.Length){
                    digits[x]=0;
                    x++;
                }
                easy=true;
                digits[i]++;
                break;
            }
            i--;
        }
        if(easy)
            return digits;
        ans.Add(1);
        foreach(var n in digits)
            ans.Add(0);
        return ans.ToArray();
    }
},5,https://leetcode.com/problems/plus-one,https://leetcode.com/problems/plus-one/solutions/3219375/c-accepted-easy-to-understand/

class Solution {
    public String addBinary(String a, String b) {
        StringBuilder res = new StringBuilder();
        int i = a.length() - 1;
        int j = b.length() - 1;
        int carry = 0;
        while(i >= 0 || j >= 0){
            int sum = carry;
            if(i >= 0) sum += a.charAt(i--) - '0';
            if(j >= 0) sum += b.charAt(j--) - '0';
            carry = sum > 1 ? 1 : 0;
            res.append(sum % 2);
        }
        if(carry != 0) res.append(carry);
        return res.reverse().toString();
    }
},3,https://leetcode.com/problems/add-binary,https://leetcode.com/problems/add-binary/solutions/1679423/well-detailed-explaination-java-c-python-easy-for-mind-to-accept-it/

class Solution {
public:
    vector<string> fullJustify(vector<string>& words, int maxWidth) {
    int left = 0;
        std::vector<string> answer;
        while (left < words.size()) {
            int right = getRightPtr(left, words, maxWidth);
            answer.push_back(justify(left, right, words, maxWidth));
            left = right + 1;
        }
        return answer;
    }
private:

    int getRightPtr(int left, vector<string>& words, int maxWidth) {
        int right = left;
        int sum = words[right++].length();
        while (right < words.size() && (sum + 1 + words[right].length()) <= maxWidth)
            sum += 1 + words[right++].length();
        return right - 1;
    }

    string justify(int left, int right, vector<string>& words, int maxWidth) {
        if (right - left == 0) return addRemSpaces(words[left], maxWidth);

        bool isLastLine = right == words.size() - 1;

        int numSpaces = right - left;

        int totalSpace = maxWidth - findLengthOfRange(left, right, words);

        string space = isLastLine ? " " : findSpaceSeq(totalSpace / numSpaces);
        int remainder = isLastLine ? 0 : totalSpace % numSpaces;

        string answer = "";
        for (int i = left; i <= right; i++) {
            answer += (words[i]) + (space) + (remainder-- > 0 ? " " : "");
        }

        int leftPtr = 0, rightPtr = answer.size() - 1;

        //removing trailing spaces
        while(left < answer.size() && answer[leftPtr]  ==  ' '){
            leftPtr++;
        }
        while(rightPtr > - 1 && answer[rightPtr] == ' '){
            rightPtr--;
        }
        return addRemSpaces(answer.substr(leftPtr, rightPtr + 1 - leftPtr), maxWidth);
        }

    string addRemSpaces(string answer, int maxWidth) {
        if (answer.length() >= maxWidth) return answer;
        return answer + string(maxWidth - answer.length(), ' ');
    }

    int findLengthOfRange(int left, int right, vector<string>& words) {
        int length = 0;
        for (int i = left; i <= right; i++) {
