class Solution {
public:
    string simplifyPath(string path) {

        stack<string> st;
        string res;

        for(int i = 0;  i<path.size(); ++i)
        {
            if(path[i] == '/')    
                continue;
            string temp;
			// iterate till we doesn't traverse the whole string and doesn't encounter the last /
            while(i < path.size() && path[i] != '/')
            {
				// add path to temp string
                temp += path[i];
                ++i;
            }
            if(temp == ".")
                continue;
			// pop the top element from stack if exists
            else if(temp == "..")
            {
                if(!st.empty())
                    st.pop();
            }
            else
			// push the directory file name to stack
                st.push(temp);
        }

		// adding all the stack elements to res
        while(!st.empty())
        {
            res = "/" + st.top() + res;
            st.pop();
        }

		// if no directory or file is present
        if(res.size() == 0)
            return "/";

        return res;
    }
};,36,https://leetcode.com/problems/simplify-path,https://leetcode.com/problems/simplify-path/solutions/1847357/c-easy-stack-simple-explained-algorithm/

class Solution {
public:
    string simplifyPath(string path) {
        stack<string> st;
        string ans="";
        for(int i=0;i<path.size();i++){
            if(path[i]=='/'){
                continue;
            }
            string temp;
            while(i<path.size() && path[i]!='/'){
                temp+=path[i];
                i++;
            }
            if(temp=="."){
                continue;
            }else if(temp==".."){
                if(!st.empty()){
                    st.pop();
                }
            }else{
                st.push(temp);
            }
        }
        while(!st.empty()){
            ans='/'+st.top()+ans;
            st.pop();
        }
        if(ans.size()==0){
            return "/";
        }
        return ans;
    }
