class Solution {
public:
    bool search(vector<int>& nums, int target) {
        int sz = nums.size();

        int left = 0, right = sz-1;
        while(left <= right){

            int midPos = left + (right - left) / 2;

            if(nums[midPos] == target)return true;

            else if(nums[midPos] == nums[left] && nums[midPos] == nums[right]){
                left++,right--;
            }

            else if(nums[midPos] >  nums[right]){ 
              if(nums[midPos] > target && nums[left] <= target){
                  right = midPos - 1;
              }else{
                  left = midPos + 1;
              }
            }else{
                if(nums[midPos] < target && nums[right] >= target){
                     left = midPos + 1;
                }else{
                     right = midPos - 1;
                }
            }
        }
        return false;
    }
};,88,https://leetcode.com/problems/search-in-rotated-sorted-array-ii,https://leetcode.com/problems/search-in-rotated-sorted-array-ii/solutions/3888775/video-solution-c-java-explanation-with-drawings/

class Solution {
public:
    vector<int> nextSmaller(vector<int> &heights,int n){
        stack<int> st;
        st.push(-1);
        vector<int> ans(n);
        for(int i=n-1;i>=0;i--){
            int curr = heights[i];
            while(st.top() != -1 and heights[st.top()] >= curr){
                st.pop();
            }
            ans[i] = st.top();
            st.push(i);
        }
        return ans;
    }
    vector<int> prevSmaller(vector<int> &heights,int n){
        stack<int> st;
        st.push(-1);
        vector<int> ans(n);
        for(int i=0;i<n;i++){
            int curr = heights[i];
            while(st.top() != -1 and heights[st.top()] >= curr){
                st.pop();
            }
            ans[i] = st.top();
            st.push(i);
        }
        return ans;
    }
    int largestRectangleArea(vector<int>& heights) {
        int n = heights.size();
        vector<int> next(n);
        next = nextSmaller(heights,n);
        vector<int> prev(n);
        prev = prevSmaller(heights,n);
        int ans = INT_MIN;
        for(int i=0;i<n;i++){
            int l = heights[i];
            if(next[i] == -1) next[i] = n;
            int b = next[i] - prev[i] - 1;
            ans = max(ans,l*b);
        } 
        return ans;
    }
