class Solution {
public:
    int largestRectangleArea(vector<int>& heights) {
        int n = heights.size(), res = 0;
        vector<int> left_small(n);
        left_small[0] = 0;
        stack<int> s;
        s.push(0);

        for(int i = 1; i < n; i++) {
            while(!s.empty() && heights[s.top()] >= heights[i]) s.pop();
            if(s.empty()) left_small[i] = 0;
            else left_small[i] = s.top()+1;
            s.push(i);
        }

        stack<int> s2;
        vector<int> right_small(n);
        right_small[n-1] = n-1;
        s2.push(n-1);

        for(int i = n-2; i >= 0; i--) {
            while(!s2.empty() && heights[s2.top()] >= heights[i]) s2.pop();
            if(s2.empty()) right_small[i] = n-1;
            else right_small[i] = s2.top() - 1;
            s2.push(i);
        }

        for(int i = 0; i < n; i++) {
            int area = heights[i] * (right_small[i]-left_small[i]+1);
            res = max(res, area);
        }
        return res;
    }
};,59,https://leetcode.com/problems/largest-rectangle-in-histogram,https://leetcode.com/problems/largest-rectangle-in-histogram/solutions/3707021/my-simple-c-solution/

class Solution {
public:
    int largestRectangleArea(vector<int>& arr) {
            int n = arr.size();
            int prevsmaller[n];
            stack<int> st;

            for (int i = 0 ; i < n ; i++) {
                while(st.size()!=0 and arr[st.top()]>=arr[i])
                    st.pop();
                if(st.size()==0){
                    prevsmaller[i]=0;
                }else{
                    prevsmaller[i]=st.top()+1;
                }
                st.push(i);
            }
            while (!st.empty())
                st.pop();

            int rigthsmaller[n];
            for (int i = n - 1 ; i >= 0 ; i--) {
                while(st.size()!=0 and arr[st.top()]>=arr[i])
                    st.pop();
                if(st.size()==0){
                    rigthsmaller[i]=n-1;
                }else{
                    rigthsmaller[i]=st.top()-1;
                }
                st.push(i);
            }
            int maxi = -100000;
            for (int i = 0 ; i < n ; i++) {
                maxi = max(maxi, ((rigthsmaller[i] - prevsmaller[i] + 1 ) * arr[i] ));
            }
            return maxi;
    }
    int maximalRectangle(vector<vector<char>>& arr) {
        int n = arr.size(),m = arr[0].size();
        vector<vector<int>> dp(n,vector<int>(m,0));
        int area = 0 ;
        for(int i = 0 ; i< n; i++){
            for(int j =0 ; j < m ; j ++){
                if(i==0){
                    dp[i][j]=arr[i][j]-'0';
                }else if(i!=0 and arr[i][j]=='1'){
                    dp[i][j]+=dp[i-1][j]+1;
                }
            }
            area = max(area, largestRectangleArea(dp[i]));
        }
        return area ;
    }
};,101,https://leetcode.com/problems/maximal-rectangle,https://leetcode.com/problems/maximal-rectangle/solutions/4179184/largestrectanglearea-prefixsum/

