/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    TreeNode* f(vector<int>& p, vector<int>& i, int& id, int l, int r)
    {
        if(l>r)
            return NULL;
        int pt=l;
        while(i[pt]!=p[id])
            pt++;
        id++;
        TreeNode* t=new TreeNode(i[pt]);
        t->left=f(p,i,id,l,pt-1);
        t->right=f(p,i,id,pt+1,r);
        return t;
    }
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        int id=0;
        return f(preorder,inorder, id, 0, inorder.size()-1);
    }
};,60,https://leetcode.com/problems/construct-binary-tree-from-preorder-and-inorder-traversal,https://leetcode.com/problems/construct-binary-tree-from-preorder-and-inorder-traversal/solutions/3200731/c-best-solution/

public class Solution {
    public int mindepth;
    public void helper(TreeNode root, int depth){
        if(root!=null){
            if(root.left==null && root.right==null){
                if(depth<mindepth)
                    mindepth=depth;
            }
            depth++;
            helper(root.left,depth);
            helper(root.right,depth);
        }
    }
    public int MinDepth(TreeNode root) {
        if(root==null) return 0;
        mindepth = Int32.MaxValue;
        helper(root,1);
