/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* reverse(ListNode *head){
        ListNode* p = NULL , *q = NULL, *r = head;
        while(r!= NULL){
            p = q;
            q = r;
            r = r -> next;

            q -> next = p;
        }
        return q;
    }
    void reorderList(ListNode* head) {
        // Logic - reverse LL after middle node
        // then take 1-1 node from both halves

        if(head == NULL || head -> next == NULL){
            return ;
        }

        ListNode* f = head -> next, *s = head;
        while(f != NULL ){
            f = f->next;
            if(f != NULL){
                f = f->next;
                s = s->next;
            }
        }

        ListNode * second = reverse(s->next);
        ListNode * first = head;
        s->next = NULL;

        // insert even node then odd node one by one
        ListNode *ansHead = new ListNode(-1);
        ListNode * ansTail = ansHead;

        while(first && second){
            //first add even
            ansTail->next = first;
            ansTail = first;
            first = first->next;

            // add odd
            ansTail->next = second;
            ansTail = second;
            second = second->next;
        }

        // in odd case LL -> first has 1 node left
        if(first != NULL){
            ansTail->next = first;
            ansTail = first;
        }


        head = ansHead->next;
    }
};,107,https://leetcode.com/problems/reorder-list,https://leetcode.com/problems/reorder-list/solutions/4253452/simple-easy-cpp-solution-with-comments/

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    void reorderList(ListNode* head)
     {
        if ((!head) || (!head->next) || (!head->next->next)) return;
        stack<ListNode*> my_stack;
        ListNode* ptr = head;
        int size = 0;
        while (ptr != NULL) 
        {
            my_stack.push(ptr);
            size++;
            ptr = ptr->next;
        }
        ListNode* pptr = head;
        for (int j=0; j<size/2; j++) 
        {
            ListNode *element = my_stack.top();
            my_stack.pop();
            element->next = pptr->next;
            pptr->next = element;
            pptr = pptr->next->next;
        }
        pptr->next = NULL;
    }
};,60,https://leetcode.com/problems/reorder-list,https://leetcode.com/problems/reorder-list/solutions/3332795/solution-in-c/

class LRUCache {
public:
    class Node{
        public: 
            int key;
            int val;
            Node* prev;
            Node* next;

            Node(int key, int val){
                this->key = key;
                this->val = val;
            }
    };

    Node* head = new Node(-1, -1);
    Node* tail = new Node(-1, -1);

    int cap;
    unordered_map<int, Node*> m;

    LRUCache(int capacity) {
        cap = capacity;
        head -> next = tail;
        tail -> prev = head;
    }

    void addNode(Node* newnode){
        Node* temp = head -> next;

        newnode -> next = temp;
        newnode -> prev = head;

        head -> next = newnode;
        temp -> prev = newnode;
    }

    void deleteNode(Node* delnode){
        Node* prevv = delnode -> prev;
        Node* nextt = delnode -> next;

        prevv -> next = nextt;
        nextt -> prev = prevv;
    }

    int get(int key) {
        if(m.find(key) != m.end()){
            Node* resNode = m[key];
            int ans = resNode -> val;

            m.erase(key);
            deleteNode(resNode);
            addNode(resNode);

            m[key] = head -> next;
            return ans;
        }
        return -1;
    }

    void put(int key, int value) {
        if(m.find(key) != m.end()){
            Node* curr = m[key];
            m.erase(key);
            deleteNode(curr);
        }

        if(m.size() == cap){
            m.erase(tail -> prev -> key);
            deleteNode(tail -> prev);
        }

        addNode(new Node(key, value));
        m[key] = head -> next;
    }
};,0,https://leetcode.com/problems/lru-cache,https://leetcode.com/problems/lru-cache/solutions/3780815/dll-map-c-java-python-beginner-friendly/

class LRUCache {
public:
    // declaring our data structures
    class Node {
    public:
        int key;
        int val;
        Node *prev;
        Node *next;

        Node (int key, int val) {
            this->key = key;
            this->val = val;
            prev = nullptr;
            next = nullptr;
        }
    };

    Node *head = nullptr;
    Node *tail = nullptr;

    unordered_map <int, Node*> map;
    int cap;
    int currSize = 0;

// functions 
    LRUCache(int capacity) {
        cap = capacity;
    }

    void pushToEnd (Node *node) {
        if (node == tail) return;
        if (node == head) {
            head = node->next;
        }
        else {
            node->prev->next = node->next;
        }
        node->next->prev = node->prev;
        node->next = nullptr;
        tail->next = node;
        node->prev = tail;
        tail = node;
    }

    void deleteLRUnode () {
        Node *temp = head->next;
        map.erase(head->key);
        delete head;
        if (!temp) {
            head = nullptr;
            tail = nullptr;
        }
        else {
            head = temp;
        }
        currSize--;
        return;
    }

    void addToEnd (Node *node) {
        map[node->key] = node;
        if (!tail) {
            head = node;
            tail = node;
        }
        else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
        currSize++;
    }


// main functions to be implemented

    int get(int key) {
        if (map.find(key) == map.end()) {
            return -1;
        }
        Node *curr = map[key];
        pushToEnd (curr);

        return curr->val;
    }

    void put(int key, int value) {
        if (map.find(key) != map.end()) {
            Node *curr = map[key];
            curr->val = value;
            pushToEnd(curr);
        }
        else {
            Node *newnode = new Node (key, value);
            if (currSize == cap) {
                deleteLRUnode();
            }
            addToEnd(newnode);
        }
    }
};,112,https://leetcode.com/problems/lru-cache,https://leetcode.com/problems/lru-cache/solutions/3959158/the-best-possible-c-answer-in-easiest-language-beats-95-using-linked-list-and-hashmap/

class Solution {
    public ListNode insertionSortList(ListNode head) {
        if (head.next == null) return head;
        ListNode headNew = head, tempOuter = head.next, lastInner = headNew, prevOuter = head;
        while (tempOuter != null) {
            ListNode tempOuterCopy = tempOuter;
            tempOuter = tempOuter.next;
            if (lastInner.val > tempOuterCopy.val) {
                if (tempOuterCopy.val < headNew.val) {
                    if (headNew.next != null && headNew.next.equals(tempOuterCopy)) {
                        headNew.next = null;
                    }
                    tempOuterCopy.next = headNew;
                    headNew = tempOuterCopy;
                } else {
                    ListNode fromHead = headNew, prevInner = headNew;
                    while (fromHead != null) {
                        if (tempOuterCopy.val < fromHead.val) {
                            prevInner.next = tempOuterCopy;
                            tempOuterCopy.next = fromHead;
                            if (fromHead.next != null && fromHead.next.equals(tempOuterCopy)) fromHead.next = null;
                            break;
                        }
                        prevInner = fromHead;
                        fromHead = fromHead.next;
                    }
                }
            } else {
                tempOuterCopy.next = null;
                lastInner.next = tempOuterCopy;
                lastInner = lastInner.next;
            }
        }
        return headNew;
    }
