        int tensandones=num%100, hundreds=num/100;
        String res="";
        if(hundreds>0) res=nums[hundreds]+" Hundred";
        num%=100;

        if(tensandones>0) 
            res+=" "+(
                (tensandones>=10 && tensandones<=19)? 
                    ten2_19[tensandones-10]: 
                    (morethan20[tensandones/10]+" "+nums[tensandones%10]).trim()
            );

        return res.trim();
    }
