class Solution {
private:

    int solveTabulation(int n)
    {
        vector<int> dp(n+1, -1);
        dp[0]=1;


        for(int i=1;i<=n;i++)
        {
            int start=1;
            int end=sqrt(n);
            int result=INT_MAX; 
            for(int j=start;j<=end;j++)
            {
                int numSquare=j*j;
                if(i-numSquare >= 0)
                {
                    int ans = 1 + dp[i-numSquare];
                    result = min(ans, result);

                }
            }
            dp[i]=result;
        }

        return dp[n];
    }

public:
    int numSquares(int n) {
        int ans = solveTabulation(n);
        return ans-1;
    }
};,84,https://leetcode.com/problems/perfect-squares,https://leetcode.com/problems/perfect-squares/solutions/4288419/memoization-tabulation-dp-all-approaches-easy-c/

class Solution {
public:
    int dp[10005];

    int solve(int n) {
        if(n == 0) return 0;
        if(dp[n] != -1) return dp[n];

        int ans = INT_MAX;
        for(int i=1; i*i <= n; i++) {
            ans = min(ans, 1 + solve(n - i*i));
        }
        return dp[n] = ans;
    }

    int numSquares(int n) {
        memset(dp, -1, sizeof(dp));
        int ans = solve(n);
        return ans;
    }
