class Solution {
public:
    bool check(string s)
    {
        if(s=="0")return true;
        if(s[0]=='0')return false;
        return true;
    }
    string string_sum(string first,string second)
    {
        string ans = "";
        int carry = 0;
        int f = first.length()-1;
        int s = second.length()-1;
        while(f>=0 && s>=0)
        {
            int sum = carry+(first[f]-'0')+(second[s]-'0');
            carry = sum/10;
            sum = sum%10;
            ans+=to_string(sum);

            f--;
            s--;
        }
        while(f>=0)
        {
            int sum = (first[f]-'0')+carry;
            carry = sum/10;
            sum = sum%10;
            ans+=to_string(sum);
            f--;
        }
        while(s>=0)
        {
            int sum = (second[s]-'0')+carry;
            carry = sum/10;
            sum = sum%10;
            ans+=to_string(sum);
            s--;
        }

        if(carry!=0)
        {
            ans+=to_string(carry);
        }
        reverse(ans.begin(),ans.end());
        return ans;

    }
    bool isAdditiveNumber(string num) {
        int n = num.length();
        if(n==1)return false;
        bool flag = false;
        int l;
        for(int i=1;i<n;i++)
        {
            for(int j=1;j<n;j++)
            {
                if(i+j>=n)
                continue;
                else
                {
                    l = i+j;
                    string first = num.substr(0,i);
                    string second = num.substr(i,j);
                    if(check(first) && check(second)==false)continue;
                    string sum = string_sum(first,second);
                    string reqsum = num.substr(i+j,sum.length());
                    if(sum!=reqsum)
                    continue;
                    else
                    {
                        bool f = true;
                        while(l<n)
                        {
                            first = second;
                            second = sum;
                            l+=second.length();
                            if(l==n)
                            {
                                break;
                            }
                            sum = string_sum(first,second);
                            reqsum = num.substr(l,sum.length());
                            if(sum!=reqsum)
                            {
                                f = false;
                                break;
                            }

                        }
                        if(f)
                        {
                            flag = true;
                            break;
                        }
                    }
                }
            }
            if(flag)
            break;
        }
        return flag;

    }
