class Solution {
    public List<List<Integer>> levelOrder(Node root) {
        List<List<Integer>> ans=new ArrayList<>();
        if(root==null)
            return ans; 
        Queue<Node> q=new LinkedList();
        q.offer(root);
        while(!q.isEmpty())
        {
            int n=q.size();
            List<Integer> help=new ArrayList();
            for(int i=0;i<n;i++)
            {
                Node temp=q.poll();
                for(Node child:temp.children)
                    q.offer(child);
                help.add(temp.val);
            }
            ans.add(help);
        }
        return ans;
    }
