class Solution {
    public String licenseKeyFormatting(String s, int k) {
        while (s.length() > 0 && s.charAt(0) == '-') s = s.substring(1);
        while (s.length() > 0 && s.charAt(s.length() - 1) == '-') s = s.substring(0, s.length() - 1);
        String[] split = s.toUpperCase().split("-");
        int len = s.length() - (split.length - 1), lenFirst = len % k == 0 ? k : len % k;
        StringBuilder sb = new StringBuilder();
        for (String str : split) sb.append(str);
        String temp = sb.toString();
        if (temp.length() <= k) return temp;
        sb.setLength(0);
        sb.append(temp,0, lenFirst).append("-");
        int i = lenFirst;
        while (i < temp.length()) {
            sb.append(temp, i, i + k).append("-");
            i += k;
        }
        sb.setLength(sb.length() - 1);
        return sb.toString();
    }
},123,https://leetcode.com/problems/license-key-formatting,https://leetcode.com/problems/license-key-formatting/solutions/3134946/java-messy-solution/

class Solution {
public:
   int findMinStep(string board, string hand) {
	vector<int> freq(26, 0);
	for(char c: hand)
		freq[c - 'A']++;
	unordered_map<string, int> cache;
	return dfs(board, freq, cache);
}

int dfs(string board, vector<int>& freq, unordered_map<string, int>& cache) {
    string key = board + "#" + serialize(freq);
	if(cache.count(key)) {
        return cache[key];
    }
	int r = INT_MAX;
	if(board.length() == 0) {           
		r = 0;
	} else {
		for(int i = 0; i < board.length(); i++) {    
			for(int j = 0; j < freq.size(); j++) {     
                bool worthTrying = false;
                if(board[i] - 'A' == j)
                    worthTrying = true;
                else if(0 < i && board[i] == board[i - 1] && board[i] - 'A' != j) 
                    worthTrying = true;

				if(freq[j] > 0 && worthTrying) {     
					board.insert(board.begin() + i, j + 'A');  
					freq[j]--;   

					string newStr = updateBoard(board);  
					int steps = dfs(newStr, freq, cache);   
					if(steps != -1) {   
						r = min(r, steps + 1);
					}

					freq[j]++; 
					board.erase(board.begin() + i);   
				}
			}
		}
	}
	if(r == INT_MAX) r = -1; 
	cache[key] = r;
	return r;
}

string updateBoard(string board) {
	 int start = 0;
	 int end = 0; 
	 int boardLen = board.length();
	 while(start < boardLen) {
		 while(end < boardLen && board[start] == board[end]) {
			 end++;  
		 }

		 if(end - start >= 3) {  
			 string newBoard = board.substr(0, start) + board.substr(end); 
			 return updateBoard(newBoard);    
		 } else {
			 start = end;
		 }
	 }
	 return board;
}

string serialize(vector<int>& freq) {
    string key = "";
    for(int i = 0; i < freq.size(); i++) {
        if(freq[i] > 0)
        key += to_string((char) i + 'A') + to_string(freq[i]);
    }
    return key;
}  
};,57,https://leetcode.com/problems/zuma-game,https://leetcode.com/problems/zuma-game/solutions/2716248/c-easy-short/

