 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */

typedef struct {
    int depth;
    int value;
} leftMostTreeData;

class Solution {
public:
    int findBottomLeftValue(TreeNode* root);

    void inorderTraversal(TreeNode* node, leftMostTreeData &l, int depth);
};
/************************************************************/
int Solution::findBottomLeftValue(TreeNode* root) {
    leftMostTreeData l;
    int depth = 0;
    /* l initialization */
    l.depth = -1;
    l.value = 0;
    inorderTraversal(root, l, depth);
    return l.value;
}
/************************************************************/
void Solution::inorderTraversal(TreeNode* node, leftMostTreeData 
        &l, int depth) {
    if (node->left != nullptr) {
        inorderTraversal(node->left, l, depth+1);
    }
    if (l.depth < depth) {
        l.depth = depth;
        l.value = node->val;
    }
    if (node->right != nullptr) {
        inorderTraversal(node->right, l, depth+1);
    }
    return;
}
