        if(root->left or root->right)
        {
          ans += "(";
          preorder(root->left,ans);
          ans += ")";
        }
        if(root->right)
        {
          ans += "(";
          preorder(root->right,ans);
          ans += ")";
        }
    }
    string tree2str(TreeNode* root) {
        string ans;
        preorder(root,ans);
        return ans;
    }
