class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        vector<int> mp(26,0); 
        for(char it:tasks) mp[it-65]++;
        sort(mp.begin(),mp.end(),greater<int>());
        while(!mp.back()) mp.erase(--mp.end());

        n++;                                                      // incrementing this because we need 1 extra unit time for this task to be done again.
        int ans = 0,diff,k,back; 
        while(mp.size()){                                         // we will run this loop till we have some task to be done
            if(mp.size()>n){                                      // if n+1 tasks are available then we will do this.
                diff = max(mp[n-1] - mp[n],1);                    // we will take next n works.
                ans+=n*diff;                                      // then we will do those works for {diff} times 
                for_each(mp.begin(), mp.begin() + n, [diff](int &x) { x-=diff;});           // then remove the task which has been done
                sort(mp.begin(),mp.end(),greater<int>());                                   // then sort task count in decending order 
                while(mp.size() and !mp.back()) mp.erase(--mp.end());                       // if some task has become zero then remove it from the mp as we have sorted the vector ot will be at last
            }else{
                k = mp.size();                   // now this is the condition when we have to wait
                back = mp.back();                // take the last task count as we will do all the task once
                ans+=(n)*back;                   // for n times 
                for_each(mp.begin(), mp.end(), [back](int &x) { x-=back;});           // now reduce the task which has been done
                while(mp.size() and !mp.back()) mp.erase(--mp.end());                 // now as work is done remove then from the mp
                if(!mp.size()) ans -= n-k;                                            // if all the task is done then we have added this extra time so we will remove it.
            }
        }
        return ans;
    }
