class Solution {
public:
    bool judgeSquareSum(int c) {
        for(int i = 2 ; i*i <= c ; i++)
        {
            int cnt = 0 ;
            if(!(c%i))
            {
                while(c%i == 0) // Count all the prime factors
                {
                    cnt++ ;
                    c /= i ;
                }
                if(i%4 == 3 && cnt%2 != 0) //If any prime factor of the form (4k+3) occurs an odd number of times.
                {
                    return false ;
                }
            }
        }
        return c%4 != 3 ; // If the number itself is a prime number and can be expressed in the form of (4k+3) -> return false.
    }
