public:
    vector<double> averageOfLevels(TreeNode* root) {
        vector<double> avg;
        double ans=0;
        double cnt=0;
        queue<TreeNode*> q;
        q.push(root);
        q.push(NULL);
        while(!q.empty())
        {
            TreeNode* temp=q.front();
            q.pop();
            if(temp==NULL)
            {
                ans/=cnt;
                avg.push_back(ans);
                cnt=0;
                ans=0;
                if(!q.empty())
                {
                    q.push(NULL);
                }
            }
            else
            {
                ans+=temp->val;
                cnt++;
                if(temp->left!=NULL)
                    q.push(temp->left);
                if(temp->right!=NULL)
                    q.push(temp->right);
            }
        }
        return avg;
    }
