            for(int j=0;j<i;j++){

                if(nums[i]>nums[j]){
            // //we have found another subsequence with the same length as the one ending at i
                    if(dp[i].first==dp[j].first+1){
                        dp[i].second+=dp[j].second;
                    }
            //we have found a new longer subsequence ending at i
                    else if(dp[i].first<dp[j].first+1){
                        dp[i].second=dp[j].second;
                        dp[i].first=dp[j].first+1;
                    }
                }
            }

            if(dp[i].first==maxi) cnt+=dp[i].second;

            else if(dp[i].first>maxi){
                maxi=dp[i].first;
                cnt=dp[i].second;
            }
        }

        return cnt;
    }
