class Solution {
public:
    int  dfs(int i,int br,string &s,vector<vector<int>> &dp){
        if(i == s.size()){
            if(br == 0) return 1;
            else return 0;
        }
        if(br < 0) return 0;
        if(dp[i][br] != -1) return dp[i][br];
        int a = 0,b = 0, c = 0;
        if(s[i] == '*'){
            a = dfs(i+1,br+1,s,dp);
            b = dfs(i+1,br,s,dp);
            c = dfs(i+1,br-1,s,dp);
        }
        else{
            if(s[i] == '(')a = dfs(i+1,br+1,s,dp);
            else c = dfs(i+1,br-1,s,dp);
        }
        return dp[i][br] = (a+b+c);
    }
    bool checkValidString(string s) {
        int n = s.size();
        vector<vector<int>> dp(n+1,vector<int>(n+1,-1));
        int cnt = 0;
        for(int i=0;i<n;i++){
            if(s[i] == '*') cnt++;
        }
        if(cnt == n) return true;
        return dfs(0,0,s,dp) > 0;
    }
