class Solution {
    public int pivotIndex(int[] nums) {
        // Initialize total sum of the given array...
        int totalSum = 0;
        // Initialize 'leftsum' as sum of first i numbers, not including nums[i]...
        int leftsum = 0;
        // Traverse the elements and add them to store the totalSum...
        for (int ele : nums)
            totalSum += ele;
        // Again traverse all the elements through the for loop and store the sum of i numbers from left to right...
        for (int i = 0; i < nums.length; leftsum += nums[i++])
            // sum to the left == leftsum.
            // sum to the right === totalSum - leftsum - nums[i]..
            // check if leftsum == totalSum - leftsum - nums[i]...
            if (leftsum * 2 == totalSum - nums[i])
                return i;       // Return the pivot index...
        return -1;      // If there is no index that satisfies the conditions in the problem statement...
    }
},120,https://leetcode.com/problems/find-pivot-index,https://leetcode.com/problems/find-pivot-index/solutions/2470014/very-easy-100-fully-explained-java-c-python-js-python3/

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    vector<ListNode*> splitListToParts(ListNode* head, int k) {
        // Intution
        // The idea in here is really very simple. First we will store the len of the linked list in a temp variable for verifing the conditions. Then, we will check if the length of the list is divisible by k or not. If it is divisble then we need to change the start and the current pointers to the null values and then add the node to the vector. Finally, return to the result.

        int size = 0;

        ListNode *temp = head;

        while(temp){
            size += 1;
            temp = temp->next;
        }


        int number = size / k;
        int remain = size % k;

        ListNode *prev  = NULL;
        ListNode *start = head;

        ListNode *curr  = head;

        int currN = 0;

        vector<ListNode *> answer;

        if(k > size){
            ListNode *currT = head;
            ListNode *prev  = NULL;
            while(k > 0){
                prev  = currT;
                if(currT) currT = currT->next;
                if(prev) prev->next = NULL;
                answer.push_back(prev);
                k--;
            }
            return answer;
        }

        for(int i = 0 ; i < size ; i++){

            prev = curr;
            curr = curr->next;
            currN += 1;

            int alpha = 0;

            if(remain > 0){
                alpha = number + 1;
            }

            else alpha = number;


            if(currN == alpha){
                answer.push_back(start);
                if(prev) prev->next = NULL;
                start = curr;
                if(remain > 0) remain -= 1;
                currN = 0;
            }

        }

        return answer;


    }
};,89,https://leetcode.com/problems/split-linked-list-in-parts,https://leetcode.com/problems/split-linked-list-in-parts/solutions/4007613/c-faster-than-95/

class Solution {
public:
    vector<ListNode*> splitListToParts(ListNode* root, int k) {
        vector<ListNode*> parts(k, nullptr);
        int len = 0;
        for (ListNode* node = root; node; node = node->next)
            len++;
        int n = len / k, r = len % k;
        ListNode* node = root, *prev = nullptr;
        for (int i = 0; node && i < k; i++, r--) {
            parts[i] = node;
            for (int j = 0; j < n + (r > 0); j++) {
                prev = node;
                node = node->next;
            }
            prev->next = nullptr;
        }
        return parts;
    }
};,32,https://leetcode.com/problems/split-linked-list-in-parts,https://leetcode.com/problems/split-linked-list-in-parts/solutions/4007652/c-8ms-easy-to-understand/

