class Solution {

    static int helper(int arr[], int idx){
        int ans = 0;

        int i = idx-1;
        int a = arr[idx];
        while(i>=0 && arr[i]<a){
            ans++;
            a=arr[i];
            i--;
        }

        i=idx+1;
        a=arr[idx];

        while(i<arr.length && arr[i]<a){
            ans++;
            a=arr[i];
            i++;
        }

        return ans+1;
    }
    public int longestMountain(int[] arr) {
        int n = arr.length;

        int max = 0;

        for(int i=1; i<n-1; i++){
            if(arr[i]>arr[i-1] && arr[i]>arr[i+1]){
                max = Math.max(max,helper(arr,i));
            }
        }
        return max;
    }
