class Solution {
public:
    bool isNStraightHand(vector<int>& hand, int groupSize) {
        if(hand.size()%groupSize!=0)return false;
        map<int,int>mp;
        for(int i=0;i<hand.size();i++){
            mp[hand[i]]++;
        }
        int grp=hand.size()/groupSize;
        while(grp){
            auto it=mp.begin();
            int val=it->first;
            mp[val]--;
            if(mp[val]==0)mp.erase(val);
            int cnt=1;
            while(cnt<groupSize && mp.find(val+cnt)!=mp.end()){
                mp[val+cnt]--;
                if(mp[val+cnt]==0)mp.erase(val+cnt);
                cnt++;
            }
            if(cnt!=groupSize)return false;
            grp--;
        }
        return true;        
    }
};,167,https://leetcode.com/problems/hand-of-straights,https://leetcode.com/problems/hand-of-straights/solutions/3155325/o-nlogn-solution-using-maps/

class Solution 
{
public:
    int maxDistToClosest(vector<int>& arr) 
    {
         //at every index we need to know the nearest left
         //at every index we need to know the nearest right 
         vector<int>right = getright(arr);
         vector<int>left  = getleft(arr);

         int ans = INT_MIN;

         for(int i=0;i<arr.size();i++)
         {
             if(arr[i] == 1) continue;

             int leftdis = (i - left[i] + 1)-1;
             int rightdis = (right[i] - i + 1)-1;

             if(left[i]!=INT_MAX and right[i]!=INT_MAX)
             {
                 if(leftdis == rightdis)
                 ans = max(ans,leftdis);
                 else
                 ans = max(ans,min(leftdis,rightdis));
             }
             else if(left[i] == INT_MAX and right[i]!=INT_MAX)
             {
                 ans = max(ans,rightdis);
             }
             else if(left[i] != INT_MAX and right[i] == INT_MAX)
             {
                 ans = max(ans,leftdis);
             }
         }
         return ans;
    }
    vector<int>getleft(vector<int>&arr)
    {
        vector<int>left(arr.size(),-1);
        for(int i=0;i<arr.size();i++)
        {
            if(i == 0)
            {
                if(arr[i] == 1)
                {
                    left[i] = i;
                }
                else if(arr[i] == 0)
                {
                    left[i] = INT_MAX;
                }
            }
            else if(i > 0)
            {
                if(arr[i] == 1)
                {
                    left[i] = i;
                }
                else if(arr[i] == 0)
                {
                    left[i] = left[i-1];
                }
            }
        }
        return left;
    }
    vector<int>getright(vector<int>&arr)
    {
         vector<int>right(arr.size(),-1);
         for(int i=arr.size()-1;i>=0;i--)
         {
             if(i == (arr.size()-1))
             {
                  if(arr[i] == 1) //someone is sitting
                  {
                      right[i] = i;
                  }
                  else if(arr[i] == 0)
                  {
                      right[i] = INT_MAX;
                  }
             }
             else if(i < (arr.size()-1))
             {
                  if(arr[i] == 1)
                  {
                      right[i] = i;
                  }               
                  else if(arr[i] == 0)
                  {
                      right[i] = right[i+1];
                  }
             }
         }
         return right;
    }
