class Solution {
public:
    bool buddyStrings(string s, string p) {
        int n=s.length(), m=p.length();
        if(n!=m) return false;

        vector<int> freq(26,0);

        int first=-1, second=-1;
        for(int i=0;i<n;i++){
            if(s[i] != p[i]){
                if(first==-1){
                    first=i;
                }else if(second==-1){
                    second=i;
                }else{
                    return false; // more than 2 mismatching characters
                }
            }
            freq[s[i]-'a']++;
        }

		// similar strings
        if(first == -1 && second == -1){
            for(int i=0;i<26;i++) if(freq[i] > 1) return true; // can swap similar characters
            return false; // all characters occur only once
        }else if(second == -1){
            return false; // exactly 1 mismatch
        }

        return (s[first]==p[second] && s[second]==p[first]); // check similarity on 2 mismatched indexes
    }
};,69,https://leetcode.com/problems/buddy-strings,https://leetcode.com/problems/buddy-strings/solutions/3710765/c-o-n-frequency-map/

class Solution {
    public boolean lemonadeChange(int[] bills) {

        int count5=0;
        int count10=0;
        int count20=0;

        for(int bill: bills){
            // if encounter 5 then collect it simply
            if(bill==5 ) count5+=5;

            else if(bill==10){
                if(count5>=5){
                    count5-=5;
                    count10+=10;
                }else return false;
            }else{

                if(count5>=5 && count10>=10){
                    count5-=5;
                    count10-=10;
                    count20+=20;
                }else if(count5>=15){
                    count5-=15;
                    count20+=20;
                } 

                else return false;
            }

        }
        return true;
    }
