/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    void getparentbyBFS(unordered_map<TreeNode*,TreeNode*>&parent,TreeNode*root){
        queue<TreeNode*>q;
        q.push(root);
        while(!q.empty()){
            int n=q.size();
            while(n--){
                TreeNode*curr=q.front();
                q.pop();
                if(curr->left){
                    parent[curr->left]=curr;
                    q.push(curr->left);
                }
                if(curr->right){
                      parent[curr->right]=curr;
                    q.push(curr->right);
                }
            }
        }
    }
   void getparentbyDFS(unordered_map<TreeNode*,TreeNode*>&parent,TreeNode*root){
       if(root==NULL)
       return;
       if(root->left!=NULL){
         parent[root->left]=root;
       }
       if(root->right!=NULL){
           parent[root->right]=root;
       }
       getparentbyDFS(parent,root->left);
        getparentbyDFS(parent,root->right);
   }
    vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
        unordered_map<TreeNode*,TreeNode*>parent;
        getparentbyDFS(parent,root);
        queue<TreeNode*>q;
        unordered_map<TreeNode*,bool>vis;
        vis[target]=true;
        q.push(target);
        int lev=0;
        while(!q.empty()){
            int n=q.size();
            if(lev==k)
                break;
            lev++;
            while(n--){
                TreeNode*curr=q.front();
                q.pop();
                if(curr->left&&!vis[curr->left]){
                    vis[curr->left]=true;
                    q.push(curr->left);
                }
                 if(curr->right&&!vis[curr->right]){
                    vis[curr->right]=true;
                    q.push(curr->right);
                }
                if(parent[curr]&&!vis[parent[curr]]){
                    vis[parent[curr]]=true; 
                    q.push(parent[curr]);
                }
            }
        }
        vector<int>ans;
        while(q.size()>0){
            ans.push_back(q.front()->val);
            q.pop();
        }
        return ans;
    }
};,2,https://leetcode.com/problems/all-nodes-distance-k-in-binary-tree,https://leetcode.com/problems/all-nodes-distance-k-in-binary-tree/solutions/3748353/super-easy-solution/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:

    void findParent(TreeNode* root, unordered_map<TreeNode*, TreeNode*> &parent_pointer, TreeNode* target){
        queue<TreeNode*> q;
        q.push(root);
        while(!q.empty()){
            TreeNode* node = q.front();
            q.pop();
            if(node->left){
                parent_pointer[node->left] = node;
                q.push(node->left);
            }
            if(node->right){
                parent_pointer[node->right] = node;
                q.push(node->right);
            }
        }
    }

    void findNodes(unordered_map<TreeNode*, TreeNode*> &parent_pointer, TreeNode* target, vector<int> &ans, int k){
        queue<TreeNode*> q;
        q.push(target);
        int dist = 0;
        unordered_map<TreeNode*, bool> visited;
        visited[target] = true;
        while(!q.empty()){
            int size = q.size();
            if(dist++ == k) break;
            for(int i=0;i<size;i++){
                TreeNode* node = q.front();
                q.pop();
                if(node->left and !visited[node->left]){
                    q.push(node->left);
                    visited[node->left] = true;
                }
                if(node->right and !visited[node->right]){
                    q.push(node->right);
                    visited[node->right] = true;
                }
                if(parent_pointer[node] and !visited[parent_pointer[node]]){
                    q.push(parent_pointer[node]);
                    visited[parent_pointer[node]] = true;
                }
            }
        }
        while(!q.empty()){
            TreeNode* node = q.front();
            q.pop();
            ans.push_back(node->val);
        }
    }

    vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
        unordered_map<TreeNode*, TreeNode*> parent_pointer;
        vector<int> ans;
        findParent(root, parent_pointer, target);
        findNodes(parent_pointer, target, ans, k);
        return ans;    
    }
};,80,https://leetcode.com/problems/all-nodes-distance-k-in-binary-tree,https://leetcode.com/problems/all-nodes-distance-k-in-binary-tree/solutions/3748178/c-double-bfs/

class Solution {
public:
    std::string decodeAtIndex(std::string inputString, int k) {
        long long decodedLength = 0; // Total length of the decoded string
        for (auto character : inputString) {
            if (isdigit(character)) {
                // If the character is a digit, update the decoded length accordingly
                decodedLength *= character - '0';
            } else {
                // If the character is a letter, increment the decoded length
                decodedLength++;
            }
        }

        // Traverse the input string in reverse to decode and find the kth character
        for (int i = inputString.size() - 1; i >= 0; i--) {
            if (isdigit(inputString[i])) {
                // If the character is a digit, adjust the length and k accordingly
                decodedLength /= (inputString[i] - '0');
                k = k % decodedLength;
            } else {
                // If the character is a letter, check if it's the kth character
                if (k == 0 || decodedLength == k)
                    return string("") + inputString[i]; // Return the kth character as a string
                decodedLength--;
            }
        }

        return ""; // Return an empty string if no character is found
    }
};,148,https://leetcode.com/problems/decoded-string-at-index,https://leetcode.com/problems/decoded-string-at-index/solutions/4094710/100-reverse-stack-commented-code/

public class Solution {
    public String decodeAtIndex(String s, int k) {
        long decodedLength = 0; 

        for (char character : s.toCharArray()) {
            if (Character.isDigit(character)) {
                decodedLength *= (character - '0');
            } else {
                decodedLength++;
            }
        }

        for (int i = s.length() - 1; i >= 0; i--) {
            char currentChar = s.charAt(i);

            if (Character.isDigit(currentChar)) {
                decodedLength /= (currentChar - '0');
                k %= decodedLength;
            } else {
                if (k == 0 || decodedLength == k) {
                    return String.valueOf(currentChar); 
                }
                decodedLength--;
            }
        }

        return ""; 
    }
