class Solution {
    public int numPermsDISequence(String S) {
        int n = S.length(), M = (int)1e9 + 7;
        int[][] dp = new int[n + 1][n + 1];
        Arrays.fill(dp[0], 1);
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                dp[i][j] = j == 0 ? 0 : dp[i][j - 1];
                if (S.charAt(i - 1) == 'D') {
                    dp[i][j] += (dp[i - 1][i - 1] - (j == 0 ? 0 : dp[i - 1][j - 1])) % M;
                    if (dp[i][j] < 0) {
                        dp[i][j] += M;
                    }
                } else {
                    dp[i][j] += j == 0 ? 0 : dp[i - 1][j - 1];
                }
                dp[i][j] %= M;
            }
        }
        return dp[n][n];
    }
