        for(int i=0; i<n; i++){
            mp[persons[i]]++;
            if(mp[persons[i]] >= mp[mxp]){
                mxp = persons[i];
            }
            ans.push_back(mxp);
        }
    }

    int q(int t) {
        int idx = (upper_bound(time.begin(),time.end(),t) - time.begin()) - 1;
        return ans[idx];
    }
};

