class Solution {
public:
    int largestComponentSize(vector<int>& nums) {
        int n = size(nums), M = *max_element(begin(nums), end(nums)), ans = 1;
        auto spf = sieve(M+1);
        UnionFind uf(n + 1);
        unordered_map<int, vector<int>> mp;           // stores {p : [indices of nums for which p is prime factor]}
        for(int i = 0; i < n; i++)                    // prime factorize nums[i]
            for(auto p : getPrimes(nums[i], spf))
                mp[p].push_back(i);

        for(auto& [prime, ids] : mp)                  // union all element index that have same prime
            for(int i = 0; i < size(ids)-1; i++) 
                uf.Union(ids[i], ids[i+1]);

        return *max_element(begin(uf.sz), end(uf.sz));
    }

    vector<int> sieve(int M) {
        vector<int> spf(M+1);
        iota(begin(spf), end(spf), 0);
        for(int i = 2; i*i < M; i++) 
            if(spf[i] == i) 
                for(int j = i*i; j < M; j += i)
                    if(spf[j] == j)
                        spf[j] = i;            
        return spf;
    }

    vector<int> getPrimes(int x, vector<int>& spf) {
        vector<int> primes;
        while (x != 1) {
            int p = spf[x];
            primes.push_back(p);
            while(x % p == 0) x /= p;
        }
        return primes;
    }
};,63,https://leetcode.com/problems/largest-component-size-by-common-factor,https://leetcode.com/problems/largest-component-size-by-common-factor/solutions/1592263/c-3-simple-solution-w-explanation-disjoint-set-union-sieve-of-eratosthenes/

class Solution {
public:
    int tallestBillboard(vector<int>& rods) {
        unordered_map<int, int> dif2hi;
        dif2hi[0] = 0;

        for (int rod : rods) {
            // Create a copy of the current height differences
            unordered_map<int, int> newdif2hi = dif2hi;

            for (auto& [dif, hi]: dif2hi) {      
                //Place the rod on the tailer side, increase the height difference
                newdif2hi[dif + rod] = max(newdif2hi[dif + rod], hi + rod);

                //Place the rod on the shorter side, decrease the height difference
                int newdif=abs(dif-rod);
                int newhi= max(hi-dif+rod, hi);
                newdif2hi[newdif] = max(newdif2hi[newdif], newhi);
            }
            dif2hi = newdif2hi;
        }
        return dif2hi[0];
    }
};

