class Solution {
public:
    int mincostTickets(vector<int>& days, vector<int>& costs) {
        vector<int> v(367,INT_MAX);//INITIALIZE ANS FOR EVERY DAY TO INFINITY
        v[366] = 0;
        int i = 0, j = 0,n = days.size();
        i = n-1;
        for(j = 365; j >=0; j--){
            if(i>=0&&days[i]==j){
                if(j+1<=366){//BUY 1-DAYS TICKET jth DAYS BY THIS WE TRAVELL j+1th DAY 
                    v[j] = min(v[j],v[j+1]+costs[0]);//INTILILIZE ANS BY v[j] = min(v[j],v[j+1]if(j+1<=366)
                }else{
                    v[j] = min(v[j],costs[0]);//other wise v[j] = min(v[j],costs[0])
                }
                if(j+7<=366){//BUY 7-DAYS TICKET jth DAYS BY THIS WE TRAVELL j+7th DAY 
                    v[j] = min(v[j],v[j+7]+costs[1]);//INTILILIZE ANS BY v[j] = min(v[j],v[j+7]if(j+7<=366)
                }else{
                    v[j] = min(v[j],costs[1]);;//other wise v[j] = min(v[j],costs[1])
                }
                if(j+30<=366){//BUY 30-DAYS TICKET jth DAYS BY THIS WE TRAVELL j+30th DAY 
                    v[j] = min(v[j],v[j+30]+costs[2]);//INTILILIZE ANS BY v[j] = min(v[j],v[j+30]if(j+30<=366)
                }else{
                    v[j] = min(v[j],costs[2]);;//other wise v[j] = min(v[j],costs[2])
                }
                i--;
            }else{
                v[j] = v[j+1];
            }
        }
        // for(int i = 0; i <= days[n-1]; i++){
        //     cout<<v[i]<<" ";
        // }
        return v[days[0]];
    }
