/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<vector<int>> verticalTraversal(TreeNode* root) {
        map<int,map<int,multiset<int>>> mp; // multiset to get the sorted order
        queue<pair<TreeNode*,pair<int,int>>> q; // [node,line,level]
        q.push({root,{0,0}});
        while(!q.empty()){
            auto it=q.front();
            q.pop();
            TreeNode* node=it.first;
            int line=it.second.first;
            int level=it.second.second;
            mp[line][level].insert(node->val);
            if(node->left) q.push({node->left,{line-1,level+1}});
            if(node->right) q.push({node->right,{line+1,level+1}});
        }
        vector<vector<int>> ans;
        for(auto itr1:mp){
            vector<int> temp;
            for(auto itr2:itr1.second){
                temp.insert(temp.end(),itr2.second.begin(),itr2.second.end());
            }
            ans.push_back(temp);
        }
        return ans;
    }
};
