class Solution(object):
    def subArray(self, nums, k):
        n = len(nums)
        map = {}
        count = 0
        start = 0
        end = 0
        while end < n:
            map[nums[end]] = map.get(nums[end], 0) + 1
            while len(map) > k:
                map[nums[start]] -= 1
                if map[nums[start]] == 0:
                    del map[nums[start]]
                start += 1
            count += end - start + 1
            end += 1
        return count

    def subarraysWithKDistinct(self, nums, k):
        return self.subArray(nums, k) - self.subArray(nums, k - 1)

