class Solution {
public:
    int maxSatisfied(vector<int>& c, vector<int>& g, int min) 
    {
        //we will make the ans in three parts
        //before the window
        //in the window
        //after the window

        //making the customers prefix vector or array
         vector<long long int>customers;
         for(int i=0;i<c.size();i++)
         {
             if(customers.size() == 0)
             {
                 customers.push_back(c[i]);
             }
             else
             {
                 long long int val = 0LL + customers.back() + c[i];
                 customers.push_back(val);
             }
         }

         //making the grumpy prefix vector or array
         vector<long long int>grumpy;
         for(int i=0;i<g.size();i++)
         {
             if(grumpy.size() == 0)
             {
                 grumpy.push_back(g[i]);
             }
             else
             {
                 long long int val = 0LL + grumpy.back() + g[i];
                 grumpy.push_back(val);
             }
         }

        //till index i how many customers can be satisfied
        vector<long long int>v(c.size(),0);
        if(g[0] == 0) v[0] = c[0];
        else if(g[0] == 1) v[0] = 0;

        for(int i=1;i<c.size();i++)
        {
            if(g[i] == 1)
            {
                v[i] = v[i-1];
            }
            else if(g[i] != -1)
            {
               v[i] = c[i] + v[i-1]; 
            }
        }

        int start = 0;
        int end = min-1;
        long long int ans = 0;

        while(end < c.size())
        {
            long long int left = 0;
            long long int mid  = 0;
            long long int right = 0;

            if(start > 0)
            {
                 left = v[start -1];
            }

            long long int customer_count = customers[end];
            if(start > 0) customer_count = customer_count - customers[start-1];
            mid = customer_count;

            if(right < c.size()-1)
            {
                right = v[v.size()-1] - v[end];
            }

            long long int val = left + mid + right;
            if(val > ans)
            ans = val;

            start++;
            end++;
        }
        //print(v);
        return ans;
    }
    void print(vector<long long int>&v)
    {
        for(int i=0;i<v.size();i++)
        {
            cout<<v[i]<<" ";
        }
        cout<<endl;
    }
