class Solution {
public:
    int shortestPathBinaryMatrix(vector<vector<int>> &grid)
{
    int n = grid.size();
    int m = grid[0].size();

    if (grid[0][0] == 1 or grid[n - 1][m - 1] == 1)
    {
        return -1;
    }

    vector<vector<int>> visited(n, vector<int>(m, 0));
    int rr[] = {-1, -1, 0, 1, 1, 1, 0, -1};
    int cc[] = {0, 1, 1, 1, 0, -1, -1, -1};
    queue<pair<pair<int, int>, int>> pq;
    pq.push({{0, 0}, 1});
    visited[0][0] = 1;

    while (!pq.empty())
    {
        int dis = pq.front().second;
        int row = pq.front().first.first;
        int col = pq.front().first.second;
        pq.pop();

        if (row == n - 1 and col == m - 1)
        {
            return dis;
        }

        for (int i = 0; i < 8; i++)
        {
            int r = row + rr[i];
            int c = col + cc[i];

            if (r >= 0 and r < n and c < m and c >= 0 and grid[r][c] == 0 and !visited[r][c])
            {
                pq.push({{r, c}, dis + 1});
                visited[r][c] = 1;
            }
        }
    }

    return -1;
}
};,94,https://leetcode.com/problems/shortest-path-in-binary-matrix,https://leetcode.com/problems/shortest-path-in-binary-matrix/solutions/3584138/simple-bfs/

class Solution {
public:
    string shortestCommonSupersequence(string s, string t) {
        int n = s.size(), m = t.size();
        vector<vector<int>> dp(n + 1, vector<int>(m + 1));

        for(int i=1; i<=n; i++) {
            for(int j=1; j<=m; j++) {
                if(s[i - 1] == t[j - 1]) dp[i][j] = 1 + dp[i - 1][j - 1];
                else dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        int i = n, j = m;
        string ans;
        while(i && j) {
            if(s[i - 1] == t[j - 1]) {
                ans += s[i - 1];
                i--, j--;
            }
            else if(dp[i - 1][j] > dp[i][j - 1]) ans += s[i - 1], i--;
            else ans += t[j - 1], j--;
        }
        while(i) ans += s[--i];
        while(j) ans += t[--j];

        reverse(ans.begin(), ans.end());
        return ans;
    }
};,78,https://leetcode.com/problems/shortest-common-supersequence,https://leetcode.com/problems/shortest-common-supersequence/solutions/3044929/bottom-up-lcs-dp-c/

class Solution {
public:
    int dp[1006][1006];
    int solve(int i, int k, int sz,int ht, vector<vector<int>>& books){
        if(i == books.size()) return 0;
        if(dp[i][k] != -1) return dp[i][k];
        if(books[i][0] <= k){
            int x;
            if(books[i][1] > ht){
                x = (books[i][1] - ht)  + solve(i+1,k-books[i][0],sz,books[i][1],books);
            }
            else x = solve(i+1,k-books[i][0],sz,ht,books);
            return dp[i][k] = min(x, books[i][1] + solve(i+1,sz-books[i][0],sz,books[i][1],books) );
        }
        return dp[i][k] = books[i][1] + solve(i+1,sz-books[i][0],sz,books[i][1],books);
    }
    int minHeightShelves(vector<vector<int>>& books, int shelfWidth) {
        memset(dp,-1,sizeof(dp));
        return books[0][1] + solve(1,shelfWidth-books[0][0],shelfWidth,books[0][1],books);
    }
