class Solution {
    int MOD=1000000007;
public:
    int topDown(int n,int k,int target,vector<vector<int>> &dp){
         if(n < 0)
            return 0;
        if(n == 0 && target == 0)
            return 1;
        if(n == 0 && target != 0) 
            return 0;
        if(n !=0 && target == 0)
            return 0;
        if(dp[n][target]!=-1)
            return dp[n][target];
        int ans = 0;
        for(int i=1; i<=k; i++) {
            int recans=0;
            if(target-i>=0)
                recans= topDown(n-1, k , target-i,dp);
            ans=((ans%MOD)+(recans%MOD))%MOD;
        }
        dp[n][target]=ans;
        return dp[n][target];
    }
    int numRollsToTarget(int n, int k, int target) {
       vector<vector<int>> dp(n+1,vector<int>(target+1,-1));
       return topDown(n,k,target,dp);
    }
};,26,https://leetcode.com/problems/number-of-dice-rolls-with-target-sum,https://leetcode.com/problems/number-of-dice-rolls-with-target-sum/solutions/3794126/easy-c-top-down-approach-dp-solution/

class Solution {
public:
    int countCharacters(std::vector<std::string>& words, std::string chars) {
        // Create a map to store character counts in the 'chars' string
        std::unordered_map<char, int> counts;

        // Count the frequency of each character in the 'chars' string
        for (char c : chars) {
            counts[c]++;
        }

        int ans = 0;
        // Loop through each word in the 'words' vector
        for (std::string word : words) {
            // Create a map to store character counts in the current 'word'
            std::unordered_map<char, int> wordCount;

            // Count the frequency of each character in the current word
            for (char c : word) {
                wordCount[c]++;
            }

            bool good = true;
            // Check if the current word can be formed from the characters in 'chars'
            for (auto& [c, freq] : wordCount) {
                // If the count of a character in 'chars' is less than the count in the current word
                if (counts[c] < freq) {
                    good = false; // The word cannot be formed, set 'good' flag to false
                    break; // Exit the loop as the word is not valid
                }
            }

            // If the word can be formed from the characters in 'chars', add its length to 'ans'
            if (good) {
                ans += word.size();
            }
        }

        return ans; // Return the total length of words that can be formed
    }
};


