class Trie {
    Trie* chars[26] {};    // initially all are null
    int endsHere = 0;      // number of words ending at a Trie node
public:
    void insert(set<char> s) {
		if(size(s) > 7) return;
        Trie* cur = this;
        for(auto c : s) {
            if(!cur -> chars[c - 'a']) 
                cur -> chars[c - 'a'] = new Trie();            
            cur = cur -> chars[c - 'a'];
        }
        cur -> endsHere++;
    }
    int dfs(string& s, Trie* cur, bool hasFirst = false) {
        int ans = hasFirst ? cur -> endsHere : 0;   // if condition-1 is satisfied, add number of words ending at this node
        for(auto c : s) 
            if(cur -> chars[c-'a'])                 // if a char from puzzle is present in Trie, explore that path
                ans += dfs(s, cur -> chars[c-'a'], hasFirst | c == s[0]);
				                                   //    ^ update everytime to store if 1st char of puzzle is seen in path till now
        return ans;
    }
};

class Solution {
public:
    vector<int> findNumOfValidWords(vector<string>& W, vector<string>& P) {
        vector<int> ans(size(P));
        Trie* root = new Trie();
        for(auto& word : W) 
            root -> insert(set<char>(begin(word), end(word)));  // inserts only unique letters of word in sorted order
        for(int i = 0; auto& puzzle : P) 
            ans[i++] = root -> dfs(puzzle, root);
        return ans;
    }
