class Solution {
public:
    int equalSubstring(string s, string t, int maxCost) 
    {
        //we need to maximize the lengt of the string (substring)
        //in t that can be changed to the corresponding substring
        //as in s while keeping the constraint in the mind;

        //as the length of the s and t are equal 

        int ans_len = 0;

        int cost = 0;

        int start = 0;
        int end   = 0;

        //traversing on the string t and checking if the particular substring can be made equal

        while(end < (s.length()))
        {
            int diff = abs(t[end] - s[end]);

            while((start <= end) and (cost + diff) > maxCost)
            {
                cost = cost - abs(t[start] - s[start]);
                start++;
            }

            cost = cost + diff;
            ans_len = max(ans_len,(end - start + 1));
            end++;
        }
        return ans_len;
    }
};,145,https://leetcode.com/problems/get-equal-substrings-within-budget,https://leetcode.com/problems/get-equal-substrings-within-budget/solutions/3339145/runtime-0-ms-beats-100/

class Solution {
    public String removeDuplicates(String s, int k) {
        Stack<Character> st = new Stack<>();
        Stack<Integer> count = new Stack<>();

        int n = s.length();

        for(int i=0; i<n; i++){
            char ch = s.charAt(i);

            if(st.size()>0 && st.peek()==ch) count.push(count.peek()+1);
            else count.push(1);

            st.push(ch);

            if(count.peek()==k){
                for(int j=0; j<k; j++){
                    st.pop();
                    count.pop();
                }
            }
        }

        StringBuilder ans = new StringBuilder();

        while(st.size()>0){
            ans.insert(0,st.pop());
        }
        return ans.toString();
    }
