class Solution {
    public int[] xorQueries(int[] arr, int[][] queries) {
        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int l = queries[i][0];
            int r = queries[i][1];
            int xor = arr[l];
            for (int j = l + 1; j <= r; j++) {
                xor ^= arr[j];
            }
            res[i] = xor;
        }
        return res;
    }
