        while(s1.length()<s.length())
        {
            for(auto it:mp)
            {
                if(it.second>0)
                {
                    s1 += it.first;
                    mp[it.first]--;
                }
            }
            for(auto it:mp)
            {
                if(it.second>0)
                {
                    temp += it.first;
                    mp[it.first]--;
                }
            }
            reverse(temp.begin(), temp.end());
            s1 += temp;
            temp.clear();
        }
        return s1;
    }
