class Solution {
public:
    bool check(string &s1 , string &s2){
        vector<int>f1(26) , f2(26);

        for(auto &x : s1) ++f1[x-'a'] ;
        for(auto &x : s2) ++f2[x-'a'] ;

        for(int i = 0 ; i < 26 ; ++i ){
            if(!f1[i]) continue ;
            for(int j = 0 ; j <= i ; ++j ){
                //ith chaarcter should handle less
                int del = min(f1[i],f2[j]) ;
                f1[i] -= del ;
                f2[j] -= del ;
            }
        }
        return (count(begin(f1),end(f1),0) == 26 and count(begin(f2),end(f2),0) == 26) ;
    }

    bool checkIfCanBreak(string s1, string s2) {

        return check(s1,s2) || check(s2,s1) ;

    }
