class Solution {
public:
    vector<vector<int>>dp;
    int MOD = 1e9 + 7;
    int fun(int cap, int mask, vector<vector<int>>&caps, int totalPerson){
        // If all person are wearing cap then this is one possible way of wearing caps.
        if(mask + 1 == (1 << totalPerson))return 1;
        if(cap > 40)return 0;
        int &ans = dp[cap][mask];
        if(ans != -1)return ans;
        ans = 0;
        // Do not include this cap in the arrangment of wearing
        ans += fun(cap + 1, mask, caps, totalPerson);
        for(auto person: caps[cap]){
            // this below condition means if person "person" is not wearing any cap then he can wore the cap "cap".
            if(!((1 << (person - 1)) & mask)){
               // If person "person" is wearing the cap "cap" the person^th bit in the mask should be turned on
                int newMask = mask | (1 << (person-1));
                ans += fun(cap + 1, newMask, caps, totalPerson);
                ans %= MOD;
            }
        }
        return ans;
    }
    int numberWays(vector<vector<int>>& hats) {
        vector<vector<int>>caps(41, vector<int>());
        for(int i = 0; i < hats.size(); i++){
            for(auto j : hats[i]){
                caps[j].push_back(i+1);
            }
        }
        // caps[i] respresents the list of persons wearing the ith cap;
        dp.assign(41, vector<int>((1 << 11), -1));
        // dp[cap][mask] represents the number of ways to wear the caps such that atleast one person must wore the cap "cap" and also all have worn the distinct cap.
        return fun(0, 0, caps, hats.size());
    }
};,57,https://leetcode.com/problems/number-of-ways-to-wear-different-hats-to-each-other,https://leetcode.com/problems/number-of-ways-to-wear-different-hats-to-each-other/solutions/2596836/c-51ms-time-complexity-easy-to-understand/

