class Solution {
public:
    vector<string> buildArray(vector<int>& target, int n) {
        vector<string> ans;  // Initialize a vector of strings to store the result.
        int i = 1;  // Initialize an integer 'i' to represent the current number.

        // Iterate through each element 'a' in the 'target' vector.
        for (auto a : target) {
            // Check if 'i' is less than 'a' and perform the following steps if true:
            while (i < a) {
                ans.push_back("Push");  // Simulate pushing the current number onto the stack.
                ans.push_back("Pop");   // Simulate popping an element from the stack.
                i++;  // Move to the next number.
            }

            ans.push_back("Push");  // Simulate pushing 'a' onto the stack.
            i++;  // Move to the next number.
        }

        return ans;  // Return the 'ans' vector containing the sequence of "Push" and "Pop" instructions.
    }
};

