class Solution {
public:
   bool iscycle(int i, int j, vector<vector<char>> &grid, vector<vector<int>> &visited, vector<vector<pair<int, int>>> &parent, int n, int m)
{
    char ch = grid[i][j];
    int rr[] = {-1, 0, 1, 0};
    int cc[] = {0, 1, 0, -1};

    queue<pair<pair<int, int>, pair<int, int>>> q;
    q.push({{i, j}, {-1, -1}});
    visited[i][j] = 1;

    while (!q.empty())
    {
        int row = q.front().first.first;
        int col = q.front().first.second;
        int parx = q.front().second.first;
        int pary = q.front().second.second;
        q.pop();

        for (int k = 0; k < 4; k++)
        {
            int r = row + rr[k];
            int c = col + cc[k];

            if (r < n and r >= 0 and c < m and c >= 0 and grid[r][c] == ch)
            {
                if (!visited[r][c])
                {
                    q.push({{r, c}, {row, col}});
                    visited[r][c] = 1;
                }
                else if (parx != r or pary != c)
                {
                    return true;
                }
            }
        }
    }
    return false;
}

bool containsCycle(vector<vector<char>> &grid)
{
    int n = grid.size();
    int m = grid[0].size();

    vector<vector<int>> visited(n, vector<int>(m, 0));
    vector<vector<pair<int, int>>> parent(n, vector<pair<int, int>>(m, {-1, -1}));

    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < m; j++)
        {
            if (!visited[i][j])
            {
                bool res = iscycle(i, j, grid, visited, parent, n, m);
                if (res)
                {
                    return true;
                }
            }
        }
    }
    return false;
}
