/*

One small idea that makes the code a lot simpler is to only accept 4 customers from customers[i] 
at a time and defer the rest into
customer[i+1].
At the end we can deal with all the waiting customers at once.

*/

class Solution {
	int rotations = 0;  // Stores number of rotations made so far.
    int profit = 0;        // Stores current profit after "rotations" rotations.
	int maxProfit = 0;  // Stores max profit reached so far.
	int bestRotations = 0;   // Stores rotations corresponding to "maxProfit".


    int bCost, rCost;  // Boarding and Running costs.
public:

    // Updates the necessary variables and computes maxProfit, bestRotations etc.
    void report(int boarded) {
        profit += (boarded*bCost - rCost);  // add the profit earned.
        rotations++;                        // count this rotation.
        if (profit > maxProfit) {           // update maximum profit.
            maxProfit = profit;
            bestRotations = rotations;
        }
    }

    int minOperationsMaxProfit(vector<int>& customers, int boardingCost, int runnningCost) {
        bCost = boardingCost;
        rCost = runnningCost;
        int n = customers.size();
        for (int i=0; i<n-1; i++) {   // For each group of customers -
            if (customers[i] > 4) {   // Limit it to just 4
                customers[i+1] += (customers[i]-4);  // Add remaining to next
                customers[i] = 4;  // update the current group.
            }
            report(customers[i]);  // generate report of this rotation
        }

        int waiting = customers[n-1]; 
        while (waiting > 0) {
            int boarded = min(4, waiting); // max 4 at a time.
            waiting -= boarded; // reduce the people in waiting
            report(boarded);  // generate report
        }

        return maxProfit > 0 ? bestRotations : -1;
    }
};,196,https://leetcode.com/problems/maximum-profit-of-operating-a-centennial-wheel,https://leetcode.com/problems/maximum-profit-of-operating-a-centennial-wheel/solutions/866375/very-easy-idea-simulation-problem-readable-code-with-comments/

class Solution {
public:
    int reqSubset(int mask, int r, int n, vector<vector<int>>& requests) {
        // Create vectors to track the incoming and outgoing requests for each node
        vector<int> indeg(n, 0), outdeg(n, 0);

        // Convert the mask into a bitset to iterate over the bits
        bitset<16> bmask(mask);

        // Iterate over the requests
        for (int i = 0; i < r; i++) {
            // Check if the corresponding bit in the mask is set
            if (bmask[i]) {
                // Increment the incoming and outgoing request counts for the nodes
                indeg[requests[i][1]]++;
                outdeg[requests[i][0]]++;
            }
        }

        // Check if the incoming and outgoing request counts are equal
        if (indeg == outdeg) {
            // Return the number of set bits in the bitset (number of requests)
            return bmask.count();
        } else {
            // Return 0 if the requests are not balanced
            return 0;
        }
    }

    int maximumRequests(int n, vector<vector<int>>& requests) {
        int r = requests.size();
        int ans = 0;

        // Calculate the maximum mask value for all combinations of requests
        int reqMask = (1 << r) - 1; // all combination bits are set to 1

        // Iterate over all possible mask values
        for (int mask = 1; mask <= reqMask; mask++) {
            // Find the maximum number of requests that can be fulfilled
            ans = max(ans, reqSubset(mask, r, n, requests));
        }

        // Return the maximum number of requests that can be fulfilled
        return ans;
    }
};
