class Solution {
    int remove(string &s, string r, int x) {
        int i = 0, ans = 0; // `i` is write pointer, `j` is read pointer. 
        for (int j = 0; j < s.size(); ++j) {
            s[i++] = s[j];
            if (i > 1 && s[i - 2] == r[0] && s[i - 1] == r[1]) i -= 2, ans += x; // We keep removing pattern string `r` when `r` shows up in the end of written part.
        }
        s.resize(i);
        return ans;
    }
public:
    int maximumGain(string s, int x, int y) {
        string a = "ab", b = "ba";
        if (x < y) swap(a, b), swap(x, y);
        return remove(s, a, x) + remove(s, b, y);
    }
};,172,https://leetcode.com/problems/maximum-score-from-removing-substrings,https://leetcode.com/problems/maximum-score-from-removing-substrings/solutions/1009028/c-greedy-o-n-time-o-1-space/

#pragma GCC optimize("O3")
class Solution {
public:
    unordered_map<int, vector<int>> adj;
    void build_adj(vector<vector<int>>& adjacentPairs){
        #pragma unroll
        for(auto& e: adjacentPairs){
            int v0=e[0], v1=e[1];
            if (adj.count(v0)) adj[v0].push_back(v1);
            else adj[v0]={v1};
            if (adj.count(v1)) adj[v1].push_back(v0);
            else adj[v1]={v0};
        }
    }
    vector<int> ans;
    void dfs(int i, int prev){
        ans.push_back(i);
        #pragma unroll
        for(int j: adj[i]){
            if (j==prev) continue;
            dfs(j, i);
        }

    }
    vector<int> restoreArray(vector<vector<int>>& adjacentPairs) {
        build_adj(adjacentPairs);
        int root=INT_MAX;
        #pragma unroll
        for(auto& [i, vec]: adj){
            if (vec.size()==1){
                root=i;
                break;
            }
        }
        ans.reserve(adjacentPairs.size()+1);
        dfs(root, INT_MAX);
        return ans;
    }
};
