var maximumScore = function (x, y, z) {
  // sort ascending
  [x, y, z] = [x, y, z].sort((a, b) => a - b);

  // make   z equal to y     by pairing with x
  // equally distribute x    to y & z
  // take min of remaining y & z

  let s = 0
  let extra = z - y
  if (x >= extra) {
    s += extra
    z -= extra
    x -= extra
  } else {
    s += x
    z -= x
    x -= x
  }

  if (x) {
    if (x % 2 === 0) {
      y -= x / 2
      z -= x / 2
      s += x
      x -= x
    } else {
      z -= 1
      x -= 1
      s += 1

      y -= x / 2
      z -= x / 2
      s += x
      x -= x
    }
  }

  s += Math.min(y, z)
  return s
};,100,https://leetcode.com/problems/maximum-score-from-removing-stones,https://leetcode.com/problems/maximum-score-from-removing-stones/solutions/3797261/javascript-1753-maximum-score-from-removing-stones/

class Solution {
public:
    int minimumSize(vector<int>& nums, int k) {
        int mx = 0;
        for(auto &i: nums){
            mx = max(mx,i);
        }
        int mn = 1,mid,x,ans;
        while(mn<=mx){
            x = 0;
            mid = (mx-mn)/2+mn;
            for(auto &i: nums){
                if(i%mid){
                    x += i/mid;
                }else{
                    x += i/mid-1;
                }
            }
            if(x>k){
                mn = mid+1;
            }else{
                ans= mid;
                mx = mid-1;
            }
        }
        return ans;
    }
