class Solution {
public:
    int longestPalindrome(string word1, string word2) {
        string s = word1 + word2;
        int dp[s.size() + 1][s.size() + 1];
        memset(dp, 0, sizeof(dp));
        int ans = 0;
        for(int i = 0; i < s.size(); ++i) {
            dp[i][i] = 1;
            for(int j = i-1; j >=0; --j){
                if(s[i] == s[j]){
                    dp[j][i] = dp[j+1][i-1] + 2;
                    if(j < word1.size() && i >= word1.size()) {
                        ans = max(ans, dp[j][i]);  // left side is in word1 and right side is in word2, that is a valid answer.
                    }
                }else{
                    dp[j][i] = max(dp[j][i-1], dp[j+1][i]);
                }
            }
        }
        return ans;
    }
};,185,https://leetcode.com/problems/maximize-palindrome-length-from-subsequences,https://leetcode.com/problems/maximize-palindrome-length-from-subsequences/solutions/1075450/c-python-javascript-dp-concat-word1-word2-and-solve-it-o-n-m-2/

var longestPalindrome = function(word1, word2) {
    const dp = Array(2001).fill(0).map(() => {return {};});
    const s = word1 + word2;
    let ans = 0;
    const solve = (i, j) => {
        if (i >= j) return i == j;
        if (dp[i][j] !== undefined) return dp[i][j];
        let res = 0;
        if (s[i] === s[j]) {
            res = solve(i + 1, j - 1) + 2;
            if (i < word1.length && j >= word1.length)
                ans = Math.max(ans, res);
        } else {
            res = Math.max(solve(i + 1, j), solve(i, j - 1));
        }
        return dp[i][j] = res;
    }
    solve(0, s.length - 1);
    return ans;
};,185,https://leetcode.com/problems/maximize-palindrome-length-from-subsequences,https://leetcode.com/problems/maximize-palindrome-length-from-subsequences/solutions/1075450/c-python-javascript-dp-concat-word1-word2-and-solve-it-o-n-m-2/

class Solution {
public:
    int minOperations(vector<int>& n1, vector<int>& n2) {
        if (6 * min(n1.size(), n2.size()) <  max(n1.size(), n2.size()) ) return -1;

        int sum1 = accumulate(begin(n1), end(n1), 0), sum2 = accumulate(begin(n2), end(n2), 0);
        if (sum1 > sum2) swap(n1, n2);

        priority_queue <int, vector<int>, greater<int>> q1(begin(n1), end(n1));
        priority_queue<int> q2(begin(n2), end(n2));

        int cnt = 0, diff = abs(sum1 - sum2);
        while (diff > 0 && q1.size() && q2.size()) {
            ++cnt;
            auto greaterToLess = q2.top() - 1, lessToGreater = 6 - q1.top();
            if (greaterToLess > lessToGreater) diff -= greaterToLess, q2.pop();
            else diff -= lessToGreater, q1.pop();
        }
        while (diff > 0 && q1.size()) diff -= 6 - q1.top(), q1.pop(), cnt++;
        while (diff > 0 && q2.size()) diff -= q2.top() - 1, q2.pop(), cnt++;
        return diff > 0 ? -1: cnt;
    }
};,128,https://leetcode.com/problems/equal-sum-arrays-with-minimum-number-of-operations,https://leetcode.com/problems/equal-sum-arrays-with-minimum-number-of-operations/solutions/3091255/c-complete-noise-keep-minimizing-difference/

class Solution {
public:
  vector<double> getCollisionTimes(vector<vector<int>>& c) {
    auto col_time = [&](int i, int j) { 
        return (double)(c[i][0] - c[j][0]) / (c[j][1] - c[i][1]); 
    };
    vector<double> res(c.size(), -1), s;
    for (int i = c.size() - 1; i >= 0; --i) {
        while (!s.empty() && (c[i][1] <= c[s.back()][1] || 
                              (s.size() > 1 && col_time(i, s.back()) >= res[s.back()])))
            s.pop_back();
        res[i] = s.empty() ? -1 : col_time(i, s.back());
        s.push_back(i);
    }
    return res;
}
