class Solution {
public:
    int reinitializePermutation(int n) {
        int count=0;
        vector<int> perm(n), arr(n,0), val; 
        for(int i=0; i<n; i++)
            perm[i]=i;
        val = perm;  // Save the initial value of perm to compare
        while(val!=arr)  // We compare with arr because we update values in arr and then copy it in perm
        {
            if(count!=0)    perm = arr;  // We copy after iteration 1
            for(int i=0; i<n; i++)
                arr[i] = i%2==0 ? perm[i/2] : perm[(n/2)+(i-1)/2] ;
            count++; 
        }
        return count;
    }
};,95,https://leetcode.com/problems/minimum-number-of-operations-to-reinitialize-a-permutation,https://leetcode.com/problems/minimum-number-of-operations-to-reinitialize-a-permutation/solutions/3688325/easy-c-solution-beginner-friendly-approach-with-explanation/

class Solution {
    public int countNicePairs(int[] nums) {
       int pairCnt = 0, mod = 1000000000 + 7;
        Map<Integer, Integer> diffFreq = new HashMap<>();
        for(int indx = 0; indx < nums.length; indx++){
           int diff = nums[indx] - findRev(nums[indx]);
           pairCnt = (pairCnt % mod + diffFreq.getOrDefault(diff, 0) % mod)%mod;
           diffFreq.put(diff, diffFreq.getOrDefault(diff, 0) + 1);
        }
        return pairCnt;
    }
    private int findRev(int num){
       int revNum = 0;
       while(num > 0){
           int digit = num % 10;
           revNum = revNum * 10 + digit;
           num /= 10;
       }
       return revNum;
    }    
},88,https://leetcode.com/problems/count-nice-pairs-in-an-array,https://leetcode.com/problems/count-nice-pairs-in-an-array/solutions/4312008/video-solution-explanation-with-drawings-in-depth-java-c/

